const chartConfig: ChartConfig = { saldoAcumulado: { label: 'Saldo acumulado', color: '#0057d8' } };
const financeUrlValue = (key: string) => typeof window === 'undefined' ? '' : new URLSearchParams(window.location.search).get(key) ?? '';
const financeUrlNumber = (key:string, fallback:number, min:number, max:number) => { const value=Number(financeUrlValue(key)); return Number.isFinite(value) && value>=min && value<=max ? value : fallback; };
const financeUrlDate = (key:string,fallback:string) => /^\d{4}-\d{2}-\d{2}$/.test(financeUrlValue(key)) ? financeUrlValue(key) : fallback;
const financeUrlDecimal = (key:string,fallback:string) => /^-?\d+(?:[.,]\d+)?$/.test(financeUrlValue(key)) ? financeUrlValue(key).replace(',','.') : fallback;
function LookupSelect({ label, value, items, onChange, disabled = false }: { label:string; value:string; items:KlmFinanceLookupItem[]; onChange:(value:string)=>void; disabled?:boolean }) {
  const hydrated=value && !items.some((item)=>item.id===value) ? [{id:value,label:'Registro removido ou inacessível',inactive:true,unavailable:true},...items] : items;
  return <label className="text-xs">{label}<select aria-label={label} value={value} disabled={disabled} onChange={(event) => onChange(event.target.value)} className="mt-1 h-9 w-full rounded-md border border-input bg-background px-2 text-xs disabled:opacity-60"><option value="">Todos / não vinculado</option>{hydrated.map((item) => <option key={item.id} value={item.id} disabled={item.unavailable}>{item.label}{item.inactive ? ' · inativo' : ''}</option>)}</select></label>;
}
function LookupSearch({ label, value, onChange, loading, hasMore, onLoadMore }: { label:string; value:string; onChange:(value:string)=>void; loading:boolean; hasMore:boolean; onLoadMore:()=>void }) {
  return <div><label className="text-xs">{label}<Input aria-label={label} value={value} onChange={(event)=>onChange(event.target.value)} placeholder="Digite para buscar" className="mt-1 min-h-11 text-base sm:min-h-9 sm:text-xs" /></label>{loading && <p className="mt-1 text-[11px] text-muted-foreground" role="status">Buscando…</p>}{hasMore && <Button type="button" size="sm" variant="ghost" className="mt-1 min-h-11 sm:min-h-8" onClick={onLoadMore} disabled={loading}>{loading?'Carregando…':'Carregar mais resultados'}</Button>}</div>;
}
const mergeLookupItems=(...groups:Array<KlmFinanceLookupItem[]|undefined>)=>{const byId=new Map<string,KlmFinanceLookupItem>();groups.flatMap((items)=>items ?? []).forEach((item)=>byId.set(item.id,item));return [...byId.values()];};
const formatExecutiveMetric = (metric: { value:number|string|null; unit:string }) => {
  if (metric.value === null) return 'Dados insuficientes';
  const value = Number(metric.value);
  if (metric.unit === 'percent') return `${value.toFixed(1)}%`;
  if (metric.unit === 'months') return `${value.toFixed(1)} meses`;
  return formatBRL(value);
};
type ValuationAnalysis = {
  range?: { low:number; base:number; high:number };
  decomposition?: { netRevenue:number; ebitdaProxy:number; method:string; periodStart?:string; periodEnd?:string };
  supportingContracts: Array<{ contractId:string; matterId:string|null; label:string; allocatedRevenue:number }>;
};
const valuationAnalysis = (assumptions:Record<string,unknown>):ValuationAnalysis => {
  const range=assumptions.range && typeof assumptions.range==='object' ? assumptions.range as Record<string,unknown> : null;
  const decomposition=assumptions.decomposition && typeof assumptions.decomposition==='object' ? assumptions.decomposition as Record<string,unknown> : null;
  const supporting=Array.isArray(assumptions.supportingContracts) ? assumptions.supportingContracts : [];
  const numeric=(value:unknown)=>typeof value==='number'||typeof value==='string' ? Number(value) : Number.NaN;
  return {
    range: range && [range.low,range.base,range.high].every((value)=>Number.isFinite(numeric(value))) ? {low:numeric(range.low),base:numeric(range.base),high:numeric(range.high)} : undefined,
    decomposition: decomposition && [decomposition.netRevenue,decomposition.ebitdaProxy].every((value)=>Number.isFinite(numeric(value))) ? {netRevenue:numeric(decomposition.netRevenue),ebitdaProxy:numeric(decomposition.ebitdaProxy),method:String(decomposition.method ?? ''),periodStart:typeof decomposition.sourcePeriodStart==='string'?decomposition.sourcePeriodStart:undefined,periodEnd:typeof decomposition.sourcePeriodEnd==='string'?decomposition.sourcePeriodEnd:undefined} : undefined,
    supportingContracts: supporting.flatMap((raw)=>{if(!raw||typeof raw!=='object')return[];const item=raw as Record<string,unknown>;const amount=numeric(item.allocatedRevenue);return typeof item.contractId==='string'&&typeof item.label==='string'&&Number.isFinite(amount)?[{contractId:item.contractId,matterId:typeof item.matterId==='string'?item.matterId:null,label:item.label,allocatedRevenue:amount}]:[];}),
  };
};

